pub struct Wave{#[cfg(feature="live-resources")]pub(super) live_enabled:bool,#[cfg(feature="live-resources")]pub(super) live_created:bool,#[cfg(feature="live-resources")]pub(super) live_walk_created:bool,#[cfg(feature="live-resources")]pub(super) live_draws:u64,plan:Option<WalkPlan>,rate:f64,pub period:f64,initial_period:f64,seed:u32,offset:f64,birth:f64,end:Option<f64>,pub mode:u32,sine:Sine,sine_started:bool,walk_started:bool,pub walk:Option<Walk>,next:u64,walk_birth:f64,pub frequency:LiveTimeline,pub depth:LiveTimeline,pub walk_gain:LiveTimeline,pub walk_value:LiveTimeline,pub output:[f32;128]}
