 pub fn set_period(&mut self,seconds:f64,period:f64)->bool{if !period.is_finite()||!(15. ..=900.).contains(&period)||!self.frequency.available(1){return false;}if !Self::property(&mut self.frequency,seconds,1./period){return false;}self.period=period;if let Some(w)=&mut self.walk{w.set_period(period);}true}
