 pub(super) fn window(birth:f64,rate:f64,frame:u64,started:&mut bool)->(usize,f64){if *started{return(0,0.);}let start=birth*rate;let ceil=((start*1024.).round()/1024.).ceil()as u64;let mut offset=ceil.saturating_sub(frame).min(128)as usize;if offset==128{return(offset,0.);}let fraction=start-ceil as f64;if fraction>0.{offset+=1;}*started=true;(offset,fraction)}
