 pub fn reset_native(&mut self,mode:u32)->bool{self.period=self.initial_period;self.sine.reset();self.sine_started=false;self.walk_started=false;self.walk=None;self.next=0;self.mode=u32::MAX;self.frequency.reset(440.);self.depth.reset(1.);self.walk_gain.reset(1.);self.walk_value.reset(1.);self.output.fill(0.);self.prepare(mode)}
 pub fn rebase_birth(&mut self,seconds:f64){self.birth=seconds;self.walk_birth=seconds;}
 pub fn can_settings(&self,mode:u32)->bool{self.frequency.available(1)&&self.depth.available(1)&&(mode==self.mode||self.walk_gain.available(1))}
