 pub(super) fn live_cold(&mut self){self.sine.live_cold_bank();self.walk_value.live_cold_capacity(512);}
 pub(super) fn live_clear(&mut self,offset:f64){self.live_enabled=true;self.live_created=false;self.live_walk_created=false;self.live_draws=0;self.offset=offset;self.mode=u32::MAX;self.sine.reset();self.sine_started=false;self.walk_started=false;self.walk=None;self.plan=None;self.next=0;self.frequency.reset(440.);self.depth.reset(1.);self.walk_gain.reset(1.);self.walk_value.reset(1.);self.output.fill(0.);}
